// Registers the controllers of the "stimeo-ui" entry point with the app's
// Stimulus application. The opt-in "stimeo-ui/positioning" and "stimeo-ui/cable"
// entry points register theirs separately (registerPositioning / registerCable):
// pin the entry point and its peer in config/importmap.rb, then uncomment its
// import and call below. An app that already owns an Action Cable consumer passes
// it to setCableConsumer (also from "stimeo-ui/cable") before registerCable, so
// both share one websocket.
// Generated by `rails g stimeo:install`. Safe to edit.
//
// To cherry-pick instead of registering the whole entry point, import controllers
// individually from "stimeo-ui/controllers/<name>_controller" and register under
// your own identifiers. Note: with a JS bundler this works as-is; with
// importmap-rails each "stimeo-ui/controllers/<name>_controller" needs its own pin
// (this generator only pins the "stimeo-ui" entrypoint), so add those pins to
// config/importmap.rb.
import { application } from "controllers/application";
import { registerStimeo } from "stimeo-ui";

registerStimeo(application);

// import { registerPositioning } from "stimeo-ui/positioning";
// registerPositioning(application);

